-- Canonical table definitions from the approved read-only schema audit; no user data.
CREATE TABLE profile_stats (   uid TEXT PRIMARY KEY,   follower_count INTEGER NOT NULL DEFAULT 0 CHECK (follower_count >= 0),   following_count INTEGER NOT NULL DEFAULT 0 CHECK (following_count >= 0),   updated_at INTEGER NOT NULL );
CREATE TABLE public_profiles (   uid TEXT PRIMARY KEY NOT NULL,   nickname TEXT NOT NULL DEFAULT '',   avatar_url TEXT NOT NULL DEFAULT '',   bio TEXT NOT NULL DEFAULT '',   is_public INTEGER NOT NULL DEFAULT 1     CHECK (is_public IN (0, 1)),   created_at INTEGER NOT NULL,   updated_at INTEGER NOT NULL , handle TEXT NOT NULL DEFAULT '', background_url TEXT NOT NULL DEFAULT '', genre_override TEXT NOT NULL DEFAULT '[]', spotify_url TEXT NOT NULL DEFAULT '', instagram_url TEXT NOT NULL DEFAULT '', tiktok_url TEXT NOT NULL DEFAULT '', profile_customized INTEGER NOT NULL DEFAULT 0 CHECK (profile_customized IN (0,1)));
CREATE TABLE track_stats (   track_id TEXT PRIMARY KEY NOT NULL,   like_count INTEGER NOT NULL DEFAULT 0 CHECK (like_count >= 0),   comment_count INTEGER NOT NULL DEFAULT 0 CHECK (comment_count >= 0),   play_count INTEGER NOT NULL DEFAULT 0 CHECK (play_count >= 0),   updated_at INTEGER NOT NULL,    FOREIGN KEY (track_id)     REFERENCES tracks(id)     ON DELETE CASCADE );
CREATE TABLE tracks (   id TEXT PRIMARY KEY NOT NULL,   owner_uid TEXT NOT NULL,    source_type TEXT NOT NULL     CHECK (source_type IN ('music_note', 'suno_library')),   source_id TEXT NOT NULL,   source_parent_id TEXT,   legacy_global_id TEXT,    source_subtrack_key TEXT NOT NULL DEFAULT '',   source_subtrack_index INTEGER,   source_subtrack_id TEXT,    title TEXT NOT NULL DEFAULT '',   description TEXT,   cover_url TEXT NOT NULL DEFAULT '',   duration_seconds REAL,    lyrics TEXT,   style TEXT,   prompt TEXT,    suno_url_primary TEXT NOT NULL,   suno_url_secondary TEXT,   search_text TEXT NOT NULL DEFAULT '',    is_public INTEGER NOT NULL DEFAULT 1     CHECK (is_public IN (0, 1)),   status TEXT NOT NULL DEFAULT 'published',    published_at INTEGER NOT NULL,   created_at INTEGER NOT NULL,   updated_at INTEGER NOT NULL , allow_next_song_apply INTEGER NOT NULL DEFAULT 0 CHECK (allow_next_song_apply IN (0, 1)), allow_follower_save INTEGER NOT NULL DEFAULT 0 CHECK (allow_follower_save IN (0, 1)), profile_pinned INTEGER NOT NULL DEFAULT 0 CHECK (profile_pinned IN (0, 1)), share_schema_version INTEGER NOT NULL DEFAULT 0, share_payload_json TEXT, primary_genre TEXT);